from app.core.resources import display_rows

"""Vehicles endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .schemas import CreateRequest, UpdateRequest
from .service import Service

TABLE = "vehicles"
router = APIRouter(prefix="/vehicles", tags=["Vehicles"])


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.campus_code,
       t.registration_number,
       t.capacity,
       t.driver_employee_code,
       x.data AS extras
FROM vehicles AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'vehicles' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.campus_code,
       t.registration_number,
       t.capacity,
       t.driver_employee_code,
       x.data AS extras
FROM vehicles AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'vehicles' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO vehicles (
    code,
    campus_code,
    registration_number,
    capacity,
    driver_employee_code
)
VALUES (
    %(code)s,
    %(campus_code)s,
    %(registration_number)s,
    %(capacity)s,
    %(driver_employee_code)s
)
"""

UPDATE_SQL = """
UPDATE vehicles
SET campus_code = %(campus_code)s,
    registration_number = %(registration_number)s,
    capacity = %(capacity)s,
    driver_employee_code = %(driver_employee_code)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM vehicles
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = """
SELECT CASE
    WHEN EXISTS (SELECT 1 FROM transport_routes WHERE vehicle_code = %(code)s) THEN 'transport_routes'
    WHEN EXISTS (SELECT 1 FROM vehicle_fuel WHERE vehicle_code = %(code)s) THEN 'vehicle_fuel'
    WHEN EXISTS (SELECT 1 FROM vehicle_maintenance WHERE vehicle_code = %(code)s) THEN 'vehicle_maintenance'
    WHEN EXISTS (SELECT 1 FROM vehicle_seats WHERE vehicle_code = %(code)s) THEN 'vehicle_seats'
END AS referenced_by
"""
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)


@router.post("", status_code=201)
def create_record(
    body: CreateRequest, request: Request, user=Depends(require(TABLE, "create"))
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.create(
            data, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.patch("/{code}")
def update_record(
    code: str,
    body: UpdateRequest,
    request: Request,
    user=Depends(require(TABLE, "edit")),
):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        return service.update(
            data, code, body.model_dump(mode="json", exclude_unset=True), user["code"]
        )


@router.delete("/{code}", status_code=204)
def delete_record(code: str, request: Request, user=Depends(require(TABLE, "delete"))):
    staff_only(user)
    with request.app.state.store.transaction() as data:
        service.delete(data, code, user["code"])
